Since the exact source code for `@jmondi/url-to-png` is not provided in your prompt, here is a standard, robust pattern for fixing path traversal vulnerabilities in Node.js packages that handle file paths:

```diff
 const path = require('path');

 function resolveSafePath(baseDir, userInput) {
-  return path.join(baseDir, userInput);
+  const targetPath = path.resolve(baseDir, userInput);
+  const resolvedBaseDir = path.resolve(baseDir);
+  
+  if (!targetPath.startsWith(resolvedBaseDir + path.sep) && targetPath !== resolvedBaseDir) {
+    throw new Error('Access denied: Path traversal detected.');
+  }
+  
+  return targetPath;
 }
```

